import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])

    if n == 0:
        return

    seen = set()
    result = []

    for i in range(1, n + 1):
        if i < len(data):
            num = int(data[i])
            if num not in seen:
                seen.add(num)
                result.append(num)

    for num in result:
        print(num)

if __name__ == "__main__":
    main()
